use ao_reason_workbench::{config::Mode,core::service::{ServiceHandle,ServiceOptions,UiCommand,SubmitError,Readiness}};
use std::{sync::Arc,time::{Duration,Instant}};
fn options(t:&tempfile::TempDir,mode:Mode)->ServiceOptions{ServiceOptions{mode,state_dir:t.path().join("native-state"),worker_exe:env!("CARGO_BIN_EXE_aw-cli").into(),gateway_key:None,gateway_model_token:None}}
fn wait(h:&mut ServiceHandle,done:impl Fn(&ao_reason_workbench::core::service::AppSnapshot)->bool){let end=Instant::now()+Duration::from_secs(10);while Instant::now()<end{if done(&h.snapshot()){return}std::thread::sleep(Duration::from_millis(15));}panic!("snapshot did not reach expected state: {:?}",h.snapshot());}
#[test]
fn start_is_explicit_and_real_never_falls_back(){let t=tempfile::tempdir().unwrap();let mut h=ServiceHandle::spawn(options(&t,Mode::Real),Arc::new(||{})).unwrap();assert!(!t.path().join("native-state").exists());let id=h.try_submit(UiCommand::StartLocal).unwrap();wait(&mut h,|s|s.readiness==Readiness::NotReady);let end=Instant::now()+Duration::from_secs(3);let result=loop{let r=h.drain_results();if !r.is_empty(){break r}assert!(Instant::now()<end);std::thread::yield_now();};assert_eq!(result[0].request_id,id);assert!(result[0].result.is_err());assert!(!t.path().join("native-state").exists());h.stop();}
#[test]
fn thirty_two_accepted_results_are_reliable_and_next_is_busy(){let t=tempfile::tempdir().unwrap();let mut h=ServiceHandle::spawn(options(&t,Mode::Local),Arc::new(||{})).unwrap();let ids:Vec<_>=(0..32).map(|_|h.try_submit(UiCommand::Status{run_id:"absent".into()}).unwrap()).collect();assert_eq!(h.try_submit(UiCommand::Status{run_id:"absent".into()}),Err(SubmitError::Busy));let end=Instant::now()+Duration::from_secs(5);let mut results=Vec::new();while results.len()<32&&Instant::now()<end{results.extend(h.drain_results());std::thread::sleep(Duration::from_millis(5));}assert_eq!(results.iter().map(|r|r.request_id).collect::<Vec<_>>(),ids);assert!(results.iter().all(|r|r.result.is_err()));assert!(h.try_submit(UiCommand::Status{run_id:"absent".into()}).is_ok());h.stop();}
#[test]
fn background_service_runs_real_local_loop_and_reopens_same_actor_and_report(){let t=tempfile::tempdir().unwrap();let mut h=ServiceHandle::spawn(options(&t,Mode::Local),Arc::new(||{})).unwrap();assert_eq!(h.snapshot().readiness,Readiness::NotStarted);assert!(!t.path().join("native-state").exists());h.try_submit(UiCommand::StartLocal).unwrap();wait(&mut h,|s|s.readiness==Readiness::Ready);let actor=h.snapshot().actor.clone().unwrap();h.try_submit(UiCommand::Dispatch{template:"sum-native-v1".into()}).unwrap();wait(&mut h,|s|s.runs.iter().any(|r|r.run.status=="unknown"));let s=h.snapshot();assert_eq!(s.runs[0].run.detail["report"]["sum"],6);assert_eq!(s.runs[0].run.detail["verification"]["state"],"owner_evidence_required");assert!(s.runs[0].run.detail["verification"]["passed"].is_null());assert!(s.runs[0].can_report);assert!(!s.runs[0].can_retry);assert_eq!(s.nodes[0].used,1);let contact=s.runs[0].run.detail["contact_at"].clone();let id=s.runs[0].run.id.clone();h.stop();wait(&mut h,|s|s.readiness==Readiness::Stopped);let mut reopened=ServiceHandle::spawn(options(&t,Mode::Local),Arc::new(||{})).unwrap();reopened.try_submit(UiCommand::StartLocal).unwrap();wait(&mut reopened,|s|s.readiness==Readiness::Ready);let s=reopened.snapshot();assert_eq!(s.actor,Some(actor));assert_eq!(s.runs[0].run.id,id);assert_eq!(s.runs[0].run.status,"unknown");assert_eq!(s.runs[0].run.detail["report"]["sum"],6);assert_eq!(s.runs[0].run.detail["verification"]["state"],"owner_evidence_required");assert!(s.runs[0].run.detail["verification"]["passed"].is_null());let reopened_contact=s.runs[0].run.detail["contact_at"].as_u64().unwrap();let first_contact=contact.as_u64().unwrap();assert!(reopened_contact>=first_contact,"reopen contact_at must not move backwards: first={first_contact}, reopened={reopened_contact}");assert_eq!(s.runs[0].run.detail["contact_source"],"authenticated runner envelope");assert_eq!(s.nodes[0].used,1);reopened.stop();}
#[test]
fn stop_finishes_all_accepted_requests_without_joining_ui(){let t=tempfile::tempdir().unwrap();let mut h=ServiceHandle::spawn(options(&t,Mode::Local),Arc::new(||{})).unwrap();let ids:Vec<_>=(0..12).map(|_|h.try_submit(UiCommand::Status{run_id:"absent".into()}).unwrap()).collect();h.stop();wait(&mut h,|s|s.readiness==Readiness::Stopped);let results=h.drain_results();assert_eq!(results.iter().map(|r|r.request_id).collect::<Vec<_>>(),ids);assert_eq!(h.try_submit(UiCommand::StartLocal),Err(SubmitError::Stopped));}
